\begin{theorem}[Relative rigidity of a torus slab]
\label{thm:rigidity-index-one}
\uses{def:chartwise-sphere-ball,thm:dehn-standard-proper}
\lean{PoincareMT.M76.exists_indexOne_lattice_rigidity}
For $|\iota|=1$ and $|\kappa|=2$, assume the standard target atlas,
irreducibility of both structures, and a boundary-preserving PL map
$\phi:H\to H$ homotopic to the identity relative to the whole boundary.
There is a PL homeomorphism $g:H\to H$ between the two structures,
homotopic both to $\phi$ and to the identity relative to that boundary.
\end{theorem}

